&reftitle.description;
public boolYaf_Session::del stringname
Remove uma chave da sessão e seu valor.

  &reftitle.parameters;


    name

A chave da sessão a remover.

  &reftitle.examples;

   Exemplo de Yaf_Session::del


<?php
class VerifyController extends Yaf_Controller_Abstract
{
    public function captchaAction()
    {
        $session = Yaf_Session::getInstance();
        $session->start();

        $expected = $session->get("captcha_code");

        // código de uso único: remove-o logo após o uso
        $session->del("captcha_code");

        if ($expected === null
            || $this->getRequest()->getPost("code") !== $expected) {
            echo "invalid captcha";
        }
    }
}
?>
